const $ = id => document.getElementById(id);
const state = { manifest: null, scenarios: new Map(), selected: null };
const key = "tss-scenario-editor-draft-v1";
const required = ["inventory","cableInventory","cableTypeRequirements","permanentConnections","cableSchedule","namingRows","racks","expectedRackPlacements","expectedEndpointPlacements","networkScenario","binderReference"];
const networkFields = { networkCircuitId: "circuitId", networkSsid: "ssid", networkWifiPassphrase: "wifiPassphrase", networkWirelessChannel: "wirelessChannel", networkApAdminPassword: "apAdminPassword", networkEnableSecret: "enableSecret", networkConsolePassword: "consolePassword", networkVtyPassword: "vtyPassword", networkMotd: "motd" };
const authoredFields = Object.values(networkFields).filter(field => field !== "wirelessChannel");
const setStatus = text => $("status").textContent = text;
const filename = id => `${id.toLowerCase().replace(/[^a-z0-9_-]+/g,"-")}.json`;
const download = (name, value) => { const a=document.createElement("a"); a.href=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)+"\n"],{type:"application/json"})); a.download=name; a.click(); URL.revokeObjectURL(a.href); };
function selected() { try { return JSON.parse($("json").value); } catch { return null; } }
function entryFor(id = state.selected) { return (state.manifest?.scenarios || []).find(entry => entry.scenarioId === id); }
function tokenValues(network = {}, scenarioId = "") { return { "{ScenarioId}":scenarioId, "{CircuitId}":network.circuitId, "{Ssid}":network.ssid, "{WifiPassphrase}":network.wifiPassphrase, "{WirelessChannel}":network.wirelessChannel, "{ApAdminPassword}":network.apAdminPassword, "{EnableSecret}":network.enableSecret, "{ConsolePassword}":network.consolePassword, "{VtyPassword}":network.vtyPassword, "{Motd}":network.motd }; }
function resolveTokens(value, network, scenarioId) { let resolved=value || ""; Object.entries(tokenValues(network,scenarioId)).forEach(([token,replacement]) => resolved=resolved.replaceAll(token,String(replacement ?? ""))); return resolved; }
function errorsFor(data, manifest) {
  const errors=[]; if (!data || typeof data!=="object") return ["JSON must be an object."];
  if(data.format!=="tss-scenario"||data.schemaVersion!==1) errors.push("format must be tss-scenario and schemaVersion must be 1.");
  ["scenarioId","displayName","sceneName"].forEach(k=>!String(data[k]||"").trim()&&errors.push(`${k} is required.`));
  if(data.sceneName!=="TSS") errors.push("Only the TSS scene is supported.");
  required.forEach(k=>data[k]===undefined&&errors.push(`${k} is required.`));
  const network=data.networkScenario || {}; authoredFields.forEach(field=>!String(network[field]||"").trim()&&errors.push(`networkScenario.${field} is required.`));
  if (![1,6,11].includes(Number(network.wirelessChannel))) errors.push("networkScenario.wirelessChannel must be 1, 6, or 11.");
  const unique=(rows,field,label)=>{const seen=new Set; (Array.isArray(rows)?rows:[]).forEach((r,i)=>{const v=String(r?.[field]??""); if(!v.trim()||v!==v.trim()||seen.has(v.toLowerCase())) errors.push(`${label} ${i+1} has a missing, padded, or duplicate ${field}.`); seen.add(v.toLowerCase());});};
  unique(data.inventory,"equipmentId","Inventory"); unique(data.cableInventory,"cableId","Cable inventory"); unique(data.permanentConnections,"connectionId","Permanent connection"); unique(data.cableTypeRequirements,"requirementId","Cable requirement");
  ["inventory","cableInventory"].forEach(k=>(data[k]||[]).forEach((r,i)=>{if(!Number.isInteger(r?.quantity)||r.quantity<0) errors.push(`${k} row ${i+1} has an invalid quantity.`)}));
  (data.racks||[]).forEach(r=>{if(!r?.rackId||r.lowestU<1||r.highestU>40||r.lowestU>r.highestU||r.firstInstallableU<r.lowestU||r.lastInstallableU>r.highestU||r.firstInstallableU>r.lastInstallableU) errors.push(`Invalid rack range: ${r?.rackId||"missing rack"}.`);});
  if(manifest){const entry=(manifest.scenarios||[]).find(x=>x.scenarioId===data.scenarioId); if(!entry) errors.push("Scenario ID is not in the manifest."); else if(entry.displayName!==data.displayName||entry.sceneName!==data.sceneName) errors.push("Scenario identity does not match its manifest entry.");}
  return errors;
}
function renderValidation(){const data=selected(), errors=errorsFor(data,state.manifest), box=$("errors"); box.innerHTML=""; if(!errors.length){box.innerHTML="<li class='ok'>Ready for Unity validation.</li>";} else errors.forEach(e=>{const li=document.createElement("li");li.textContent=e;box.append(li)}); return errors;}
function renderBinder(){const root=$("binder"), data=selected(), network=data?.networkScenario; root.innerHTML=""; const binder=data?.binderReference; if(!binder){root.innerHTML="<p>No binder content available.</p>";return;} Object.values(binder).forEach(section=>{if(!section)return;const n=$("binderTemplate").content.cloneNode(true);n.querySelector("h3").textContent=section.sectionTitle||"Untitled section";n.querySelector("strong").textContent=resolveTokens(section.scenarioHeading,network,data?.scenarioId);n.querySelector("p").textContent=[section.intro,section.paragraph,section.note,section.endingParagraph].filter(Boolean).map(value=>resolveTokens(value,network,data?.scenarioId)).join("\n\n");const rows=n.querySelector("dl");(section.rows||[]).forEach(row=>{const label=document.createElement("dt"),value=document.createElement("dd");label.textContent=row.label||"";value.textContent=resolveTokens(row.value,network,data?.scenarioId);rows.append(label,value);});root.append(n)});}
function renderGuided(data=selected()) { const network=data?.networkScenario; $("guidedAuthoring").hidden=!data; if(!data || !network) return; $("basicScenarioId").value=data.scenarioId||""; $("basicDisplayName").value=data.displayName||""; $("basicDescription").value=entryFor()?.description||""; $("basicSceneName").value=data.sceneName||"TSS"; Object.entries(networkFields).forEach(([id,field]) => $(id).value=network[field] ?? ""); }
function save({syncGuided=false}={}) { const data=selected(); if(!data)return; state.scenarios.set(state.selected,data); localStorage.setItem(key,JSON.stringify({manifest:state.manifest,scenarios:[...state.scenarios.entries()],selected:state.selected})); renderValidation(); renderBinder(); if(syncGuided) renderGuided(data); }
function selectScenario(id){state.selected=id; const data=state.scenarios.get(id); $("json").value=JSON.stringify(data,null,2); $("json").disabled=false; ["validate","downloadScenario","downloadManifest"].forEach(x=>$(x).disabled=false); renderGuided(data); renderValidation();renderBinder();}
function populate(selectedId = state.selected){const select=$("scenarioSelect");select.innerHTML=""; (state.manifest?.scenarios||[]).forEach(e=>{if(!state.scenarios.has(e.scenarioId))return;const o=new Option(e.displayName,e.scenarioId);select.add(o)});select.disabled=!select.options.length;if(select.options.length)selectScenario(selectedId && state.scenarios.has(selectedId) ? selectedId : select.value);setStatus(`${state.scenarios.size} scenario${state.scenarios.size===1?"":"s"} loaded.`)}
function writeGuidedField(field, value) { const data=selected(); if(!data) return; data.networkScenario ||= {}; data.networkScenario[field]=field === "wirelessChannel" ? Number(value) : value; $("json").value=JSON.stringify(data,null,2); save(); }
function writeBasicField(field, value) { const data=selected(), entry=entryFor(); if(!data || !entry) return; data[field]=value; entry[field]=value; $("json").value=JSON.stringify(data,null,2); if(field === "displayName") $("scenarioSelect").selectedOptions[0].textContent=value || "Untitled scenario"; save(); }
function renameScenario() { const data=selected(), oldId=state.selected, entry=entryFor(), newId=$("basicScenarioId").value.trim(); if(!data || !entry || newId===oldId) return; if(!/^[A-Za-z0-9_-]+$/.test(newId) || state.scenarios.has(newId)) { setStatus("Scenario ID must be unique and use only letters, numbers, hyphens, or underscores."); renderGuided(data); return; } data.scenarioId=newId; entry.scenarioId=newId; entry.jsonFile=filename(newId); state.scenarios.delete(oldId); state.scenarios.set(newId,data); state.selected=newId; $("json").value=JSON.stringify(data,null,2); populate(newId); save(); }
async function loadWorkspace(){const root="../../../Assets/StreamingAssets/Scenarios/";const manifest=await fetch(root+"manifest.json").then(r=>r.json());const scenarios=await Promise.all(manifest.scenarios.map(async e=>[e.scenarioId,await fetch(root+e.jsonFile).then(r=>r.json())]));state.manifest=manifest;state.scenarios=new Map(scenarios);populate();save();}
$("loadWorkspace").onclick=()=>loadWorkspace().catch(e=>setStatus(`Could not load shipped samples: ${e.message}`));
$("importFiles").onchange=async e=>{const files=await Promise.all([...e.target.files].map(async f=>[f.name,JSON.parse(await f.text())]));const manifest=files.map(x=>x[1]).find(x=>x?.format==="tss-scenario-manifest");if(!manifest)return setStatus("Import must include manifest.json.");state.manifest=manifest;state.scenarios=new Map(files.map(x=>x[1]).filter(x=>x?.format==="tss-scenario").map(x=>[x.scenarioId,x]));populate();save();};
$("scenarioSelect").onchange=e=>selectScenario(e.target.value); $("json").oninput=()=>save({syncGuided:true}); $("validate").onclick=()=>{const e=renderValidation();setStatus(e.length?`${e.length} issue${e.length===1?"":"s"} found.`:"Browser validation passed; run Unity tests before release.")};
$("downloadScenario").onclick=()=>{const data=selected(), entry=entryFor();if(data)download(entry?.jsonFile||filename(data.scenarioId),data)};$("downloadManifest").onclick=()=>state.manifest&&download("manifest.json",state.manifest);$("clearDraft").onclick=()=>{localStorage.removeItem(key);setStatus("Saved draft cleared.")};
$("basicScenarioId").onchange=renameScenario; $("basicDisplayName").oninput=e=>writeBasicField("displayName",e.target.value); $("basicDescription").oninput=e=>{const entry=entryFor();if(entry){entry.description=e.target.value;save();}}; Object.entries(networkFields).forEach(([id,field]) => $(id).oninput=e=>writeGuidedField(field,e.target.value));
try {const draft=JSON.parse(localStorage.getItem(key));if(draft?.manifest){state.manifest=draft.manifest;state.scenarios=new Map(draft.scenarios);state.selected=draft.selected;populate(draft.selected);setStatus("Recovered local draft.");}}catch{}
